// Stateless gateway, stateful workflow: the checkpoint lives in the workflow's static data.
// Scope 'global' on purpose - 'node' data is private to the node that wrote it.
const sd = $getWorkflowStaticData('global');

return [{ json: { since: sd.since || null } }];

// Failed poll: checkpoint stays as is, the next run retries the same window.
// A few failures (cold start, rate limit) are normal; 6 in a row (~2 h) fail the run on purpose
// so an Error Workflow (workflow settings) can alert you.
const sd = $getWorkflowStaticData('global');
sd.fails = (sd.fails || 0) + 1;
if (sd.fails >= 6 && sd.fails % 6 === 0) {
  throw new Error(`KSeF Gateway failed ${sd.fails} polls in a row: ` + JSON.stringify($input.first().json).slice(0, 300));
}
return [];

// The new checkpoint is only REMEMBERED (pending) here and committed after delivery,
// so a failure midway doesn't skip invoices - the next run takes the same window.
const sd = $getWorkflowStaticData('global');
const data = $input.first().json.data;

sd.pending = data.nextSince;
sd.fails = 0;

return [{ json: data }];

// Nothing new: commit the remembered checkpoint and finish.
const sd = $getWorkflowStaticData('global');
if (sd.pending) sd.since = sd.pending;
return [{ json: { since: sd.since } }];

// The whole batch is saved and notified: move the checkpoint.
const sd = $getWorkflowStaticData('global');
if (sd.pending) sd.since = sd.pending;
return [{ json: { since: sd.since } }];
